function extractFields(jsonArray, fields) {
  const result = new Array(jsonArray.length);
  const tmp = {};
  for (let i = 0; i < jsonArray.length; i++) {
    const src = jsonArray[i];
    for (const f of fields) tmp[f] = src[f];
    result[i] = { ...tmp };
  }
  return result;
}

